namespace sv_e3a56489694545668525181e9709ce13.Services;

public class WarehouseState
{
    public string WarehouseId { get; set; } = "WH-1";
    public string WarehouseName { get; set; } = "Warehouse A";

    public static readonly Dictionary<string, string> AvailableWarehouses = new()
    {
        ["WH-1"] = "Warehouse A",
        ["WH-2"] = "Warehouse B",
        ["WH-3"] = "Warehouse C",
    };
}

namespace sv_e3a56489694545668525181e9709ce13.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts and notifies all subscribers.
/// Scoped lifetime ensures each circuit (user) gets an independent instance.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private string? _currentWarehouseId;

    public int LatestAlertCount { get; private set; }

    /// <summary>
    /// Raised whenever new alert data arrives. Subscribers must wrap
    /// StateHasChanged in InvokeAsync because this fires from a timer thread.
