@* Interactive island inside the static MainLayout top-row *@
@rendermode InteractiveServer
@inject CascadingValueSource<WarehouseState> WarehouseSource
@inject InventoryAlertService AlertService

<div class="d-flex align-items-center">
    <label class="me-2 mb-0 text-nowrap"><strong>Warehouse:</strong></label>
    <select class="form-select form-select-sm" style="width:auto"
            value="@_selectedId" @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.AvailableWarehouses)
        {
            <option value="@wh.Key">@wh.Value</option>
        }
    </select>
</div>

@code {
    private string _selectedId = "WH-1";

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        _selectedId = e.Value?.ToString() ?? "WH-1";
        var name = WarehouseState.AvailableWarehouses.GetValueOrDefault(_selectedId, "Unknown");

        var newState = new WarehouseState
        {
            WarehouseId = _selectedId,
            WarehouseName = name
        };

        // Push to all [CascadingParameter] subscribers across render modes
        await WarehouseSource.NotifyChangedAsync(newState);

        // Immediately refresh alert data for the new warehouse
        await AlertService.RefreshNowAsync(_selectedId);
    }
}

@* Reusable alert badge — subscribes to InventoryAlertService events.
   Works in both sidebar (NavMenu) and page content. *@
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.LatestAlertCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-2">@AlertService.LatestAlertCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-2">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Timer fires off the Blazor sync context, so wrap in InvokeAsync
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<p>Currently viewing: <strong>@Warehouse?.WarehouseName</strong></p>

<div class="card mb-4" style="max-width: 26rem;">
    <div class="card-header d-flex justify-content-between align-items-center">
        <span>Low-Stock Alerts</span>
        <AlertBadge />
    </div>
    <div class="card-body">
        @if (AlertService.LatestAlertCount > 0)
        {
            <p class="text-danger">
                ⚠️ <strong>@AlertService.LatestAlertCount</strong> item(s) are below minimum stock levels.
            </p>
        }
        else
        {
            <p class="text-success">✅ All items are sufficiently stocked.</p>
        }
        <small class="text-muted">Refreshes every 10 seconds. Last update: @_lastUpdate.ToString("T")</small>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseState? Warehouse { get; set; }

    private Action? _handler;
    private DateTime _lastUpdate = DateTime.Now;
    private string? _activeWarehouseId;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(() =>
        {
            _lastUpdate = DateTime.Now;
            StateHasChanged();
        });
        AlertService.OnChange += _handler;
    }

    protected override void OnParametersSet()
    {
        var whId = Warehouse?.WarehouseId ?? "WH-1";

        // (Re)start polling whenever the cascaded warehouse changes
        if (_activeWarehouseId != whId)
        {
            _activeWarehouseId = whId;
            AlertService.StartPolling(whId);
        }
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
        AlertService.StopPolling();
    }
}

